SELECT 
FROM learning_extraction_run
WHERE message_uid = #{messageUid}
  AND extractor_type = #{extractorType}
LIMIT 1

SELECT 
FROM learning_extraction_run
WHERE extractor_type = #{extractorType}
  AND status = 'pending'
ORDER BY created_at ASC, id ASC

    LIMIT #{limit}

SELECT 
FROM learning_extraction_run
WHERE extractor_type = #{extractorType}
  AND status = 'pending'
  AND user_id = #{userId}
  AND created_at >= #{from}
  AND created_at < #{to}
ORDER BY created_at ASC, id ASC

    LIMIT #{limit}
